"""Generated by generators/linear_recurrence.py (dynamic programming). Do not edit by hand; regenerate instead."""

COEFFS = (2, 3)
INIT = (0, 1)
MASK = (1 << 64) - 1


def solve(n: int) -> int:
    """Keep the last k values; Theta(k n)."""
    k = len(INIT)
    if n < k:
        return INIT[n]
    window = list(INIT)  # a(m-k), ..., a(m-1)
    for _ in range(k, n + 1):
        nxt = 0
        for i, c in enumerate(COEFFS, 1):
            if c:
                nxt += c * window[-i]
        window.append(nxt & MASK)
        del window[0]
    return window[-1]
